#include "Audio/Public/AudioCapture.h"
#include "Kismet/GameplayStatics.h"
#include "Engine/World.h"
#include "Logging/LogMacros.h"

// Define a log category for clean logging
DEFINE_LOG_CATEGORY_STATIC(LogMyGameModeAudio, Log, All);

AMyGameMode::AMyGameMode()
{
    // Set defaults if necessary
}

void AMyGameMode::BeginPlay()
{
	Super::BeginPlay();

	// Example: Start the capture process when the game mode starts
	StartAudioCapture();
}

void AMyGameMode::StartAudioCapture()
{
	if (!GetWorld())
	{
		UE_LOG(LogMyGameModeAudio, Error, TEXT("World is not valid. Cannot start Audio Capture."));
		return;
	}

	// 1. Get the Audio Subsystem
	UAudioDevice* AudioDevice = UGameplayStatics::GetAudioDevice(GetWorld());
	if (!AudioDevice)
	{
		UE_LOG(LogMyGameModeAudio, Error, TEXT("Failed to retrieve Audio Device."));
		return;
	}

	// 2. Create the Capture Instance
	// Note: Creating the object is one step; binding it to a device/source is another.
	// This is highly simplified for demonstration.
	CaptureDevice = MakeUnique<UAudioCapture>();

	if (!CaptureDevice.IsValid())
	{
